head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > removeColumnClass]<br/>Body Column 정보를 사용하여 특정 Body Column 에 설정된 CSS 클래스를 제거합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 CSS 클래스를 제거할 Body Column 의 ID 를 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (기본 4행)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (Body Column ID: col1 ~ col4, 전부 표시)
    await $c.gcm.createBasicGridView(cList);
}



scwin.btn_setColumnClass_onclick = function () {
    let columnInfo = par_columnInfo.getValue();

    // 제거 검증 준비: 해당 Body Column 에 'cRed cBlue' CSS 클래스를 설정
    target1.setColumnClass(columnInfo, "cRed cBlue");
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnClass(" + columnInfo + ", cRed cBlue)");

    // getColumnClass 로 설정값 확인
    let rtn = target1.getColumnClass(columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnClass(" + columnInfo + ") : " + rtn);
}



scwin.btn_removeColumnClass_onclick = function () {
    let columnInfo = par_columnInfo.getValue();
    let className = par_className.getText();

    // Column ID 로 Body Column 에 설정된 CSS 클래스 제거
    target1.removeColumnClass(columnInfo, className);
    wf_body_bottom.getObj("scwin").setReturnValue("removeColumnClass(" + columnInfo + ", " + className + ")");

    // getColumnClass(store) 로 제거 후 남은 설정값 확인 (전부 제거 시 undefined)
    let rtn = target1.getColumnClass(columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnClass(" + columnInfo + ") : " + rtn);

    // (@spec) Body Column 에 속한 모든 Cell 의 td 요소에서 CSS 클래스가 제거되었는지 확인
    //  - Column ID 를 인덱스로 변환하여 td 조회, getRowCount() 만큼만 출력 (viewport 빈 행 제외)
    //  - 공백 구분 복수 중 일부만 제거 시 store(getColumnClass) 와 td 잔존 클래스를 함께 확인
    let colIndex = target1.getColumnIndex(columnInfo);
    let tdList = document.querySelectorAll("td[id*='target1_cell_'][id$='_" + colIndex + "']");
    for (let i = 0; i < target1.getRowCount(); i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " td className : " + tdList[i].className);
    }
}
